/**
 * Separate the entry's files into downloadable and skipped.
 *
 * Downloadable: has a URL and not pre-skipped by Classify attachments.
 * Skipped: already classified or missing URL.
 *
 * Output 1: Has downloadable files → proceed to split/download
 * Output 2: Nothing to download   → return entry unchanged
 */
const entry = msg.payload;
const files = entry.files || [];

// All files already classified as skipped by Classify attachments — nothing to download
if (files.every(f => f.skipped)) {
    return [null, msg];
}

const to_download = [];
const skipped     = [];

files.forEach(file => {
    if (file.skipped || !file.url) {
        skipped.push(file);
    } else {
        to_download.push(file);
    }
});

if (to_download.length === 0) {
    return [null, msg];
}

msg._dl = {
    entry_backup:    JSON.parse(JSON.stringify(entry)),
    skipped_files:   skipped,
    connection_name: msg.metadata.connection_name,
    message_id:      entry.id,
    metadata:        msg.metadata
};

msg.payload = to_download;
return [msg, null];

/**
 * Build an HTTP GET request to download one file from WaSOS.
 * Saves msg.parts so the join node can reassemble after the request.
 * Clears residual HTTP state to prevent header contamination.
 */
const file     = msg.payload;
const source   = msg.metadata.source;
const base_url = global.get("parat_bridge").base_urls.wasos;

msg._saved_parts = msg.parts;
msg._saved_dl    = msg._dl;

msg._file_meta = {
    url:  file.url,
    name: file.name || "unknown_file",
    type: file.type || "application/octet-stream",
    size: file.size || 0
};

delete msg.statusCode;
delete msg.headers;
delete msg.responseUrl;
delete msg.redirectList;
delete msg.retry;
delete msg.responseCookies;

msg.url     = base_url + file.url;
msg.headers = { "x-api-key": source.client_specific.api.key };

return msg;

/**
 * On successful download: store binary via global.set("files.key", buffer).
 * The custom context store (bridge-context-store.js) writes this to
 * /data/bridge-files/files/{key} on disk automatically.
 *
 * Stores context_key on the file result so Upload files to Rayvn
 * can retrieve it later with global.get("files.key").
 *
 * On failure: return clean file object for join (no context_key set).
 *
 * Output 1: Stored successfully → join
 * Output 2: Download failed     → join (no context_key)
 */
const meta = msg._file_meta;

if (msg.statusCode === 200 && msg.payload && msg.payload.length > 0) {
    const dl       = msg._saved_dl;
    const filename = meta.name.replace(/[\\\/:*?"<>|]/g, "_");
    const key      = dl.message_id + "---" + dl.connection_name + "---" + filename;

    global.set("files." + key, msg.payload);
    node.log("File stored: " + key + " (" + msg.payload.length + " bytes)");

    return [{
        _msgid: msg._msgid,
        parts:  msg._saved_parts,
        _dl:    msg._saved_dl,
        payload: {
            url:         meta.url,
            name:        meta.name,
            type:        meta.type,
            size:        meta.size,
            context_key: key
        }
    }, null];

} else {
    node.warn("File download failed. Status: " + msg.statusCode
           + ", file: " + meta.name);

    return [null, {
        _msgid: msg._msgid,
        parts:  msg._saved_parts,
        _dl:    msg._saved_dl,
        payload: {
            url:  meta.url,
            name: meta.name,
            type: meta.type,
            size: meta.size
        }
    }];
}

/**
 * Combine downloaded files with skipped files and
 * rebuild the original entry with updated file references.
 */
const dl         = msg._dl;
const entry      = dl.entry_backup;
const skipped    = dl.skipped_files;
const downloaded = Array.isArray(msg.payload) ? msg.payload : [msg.payload];

entry.files = [...downloaded, ...skipped];

node.log("File download complete for entry " + entry.id + ": "
       + downloaded.filter(f => f.context_key).length + " stored, "
       + downloaded.filter(f => !f.context_key).length + " failed, "
       + skipped.length + " skipped");

return {
    _msgid:   msg._msgid,
    payload:  entry,
    metadata: dl.metadata
};
